# 與 api/calibration.py 的 SEAT_POSITIONS 相同（migration 不 import 會變動的程式碼，保持可重跑）
_SEAT_POSITIONS = {
    'right_back': (0.82, 0.18), 'right_mid': (0.82, 0.42), 'right_front': (0.82, 0.72),
    'center_back': (0.50, 0.18), 'center_front': (0.50, 0.72),
    'left_front': (0.18, 0.72), 'left_mid': (0.18, 0.42), 'left_back': (0.18, 0.18),
}


def copy_session_baselines(apps, schema_editor):
    """以前存在入座紀錄上的校正值，搬到使用者身上（每人取最近一次），已校正過的人不用重做。"""
    ChairSession = apps.get_model('api', 'ChairSession')
    UserCalibration = apps.get_model('api', 'UserCalibration')
    done = set()
    for session in ChairSession.objects.exclude(baseline_seat__isnull=True).order_by('-started_at'):
        seat = session.baseline_seat or {}
        if session.user_id in done or not all(k in seat for k in _SEAT_POSITIONS):
            continue
        weights = {k: max(float(seat[k] or 0), 0.0) for k in _SEAT_POSITIONS}
        total = sum(weights.values())
        if total <= 0:      # 校準模式的 delta 值（可能為負）或空值，無法算重心
            continue
        UserCalibration.objects.create(
            user_id=session.user_id, method='backend', samples=0,
            neutral_x=round(sum(w * _SEAT_POSITIONS[k][0] for k, w in weights.items()) / total, 4),
            neutral_y=round(sum(w * _SEAT_POSITIONS[k][1] for k, w in weights.items()) / total, 4),
            baseline_seat=seat, baseline_back=session.baseline_back,
            device_id=session.chair.device_id if session.chair_id else '',
        )
        done.add(session.user_id)


def backfill_records_and_notifications(apps, schema_editor):
    """多椅子之前的自動紀錄都來自唯一一張椅子（chair_01）；以前的週報通知標上 weekly 類型。"""
    Chair = apps.get_model('api', 'Chair')
    PostureRecord = apps.get_model('api', 'PostureRecord')
    Notification = apps.get_model('api', 'Notification')
    legacy, _ = Chair.objects.get_or_create(device_id='chair_01')
    PostureRecord.objects.filter(source='auto', chair__isnull=True).update(chair=legacy)
    Notification.objects.filter(message__startswith='【每週坐姿報告】').update(kind='weekly')


